import sys

def solve():
    input_data = sys.stdin.read().split()
    t = int(input_data[0])
    results = []

    for i in range(1, t + 1):
        cards = input_data[i]
        if cards == "abc":
            results.append("YES")
        elif cards in ["acb", "bac", "bca", "cab", "cba"]:
            results.append("YES")
        else:
            results.append("NO")

    for result in results:
        print(result)

if __name__ == '__main__':
    solve()
